@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  /* Leather Luxe: skeuomorphic premium fintech. Warm near-black canvas,
     cognac leather primary surfaces with stitched detailing, glass-sheen
     raised dark controls, recessed wells for fields, mint signal accent. */
  --background: oklch(0.165 0.005 65);
  --foreground: oklch(0.96 0.006 80);

  --card: oklch(0.205 0.006 65);
  --card-foreground: oklch(0.96 0.006 80);

  /* Glass overlay surface: warm charcoal at 92%, blurred by components. */
  --popover: oklch(0.225 0.007 65 / 0.92);
  --popover-foreground: oklch(0.96 0.006 80);

  /* Cognac leather. The gradient stack below is the actual material;
     this flat token is the mid tone for plain fills and rings. */
  --primary: oklch(0.55 0.115 52);
  --primary-foreground: oklch(0.975 0.014 80);

  --secondary: oklch(0.25 0.008 65);
  --secondary-foreground: oklch(0.93 0.008 80);

  --muted: oklch(0.235 0.007 65);
  --muted-foreground: oklch(0.65 0.012 70);

  --accent: oklch(0.265 0.009 65);
  --accent-foreground: oklch(0.96 0.006 80);

  --destructive: oklch(0.52 0.16 28);
  --destructive-foreground: oklch(0.975 0.012 50);

  /* Mint payment-signal accent, used by charts and status dots. */
  --mint: oklch(0.85 0.12 162);

  --border: oklch(1 0 0 / 0.08);
  /* Recessed field wells sit darker than the card they are pressed into. */
  --input: oklch(0.14 0.005 65);
  --ring: oklch(0.62 0.115 55);

  /* Hairline glass highlight for rims on raised surfaces. */
  --highlight: oklch(1 0 0 / 0.1);
  --well: oklch(0.14 0.005 65);

  /* Radius scale lives in :root (not only @theme) so the showcase, which
     injects :root vars at runtime, renders Leather Luxe radii instead of
     the host app's. Controls map onto these steps, never arbitrary px. */
  --radius: 1rem;
  --radius-xs: 0.375rem;
  --radius-sm: 0.625rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.25rem;
  --radius-2xl: 1.5rem;

  /* ── Material recipes ─────────────────────────────────────────────── */
  /* Cognac leather: lit from above, dark saddle at the base. */
  --gradient-leather: linear-gradient(
    180deg,
    oklch(0.63 0.115 56),
    oklch(0.55 0.115 52) 48%,
    oklch(0.465 0.105 48)
  );
  /* Raised dark glass: charcoal pill catching light on its top edge. */
  --gradient-raised: linear-gradient(
    180deg,
    oklch(0.275 0.008 65),
    oklch(0.215 0.007 65)
  );

  /* ── Shadow recipes ───────────────────────────────────────────────── */
  /* Leather CTA: glass sheen on top, saddle-dark base, deep warm drop. */
  --shadow-leather:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.28),
    inset 0 -0.125rem 0.1875rem oklch(0 0 0 / 0.3),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.35),
    0 0.375rem 1rem -0.25rem oklch(0 0 0 / 0.3);
  /* Scaled-down leather, for filled controls (checkbox, switch, slider). */
  --shadow-leather-sm:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.25),
    inset 0 -0.0625rem 0.125rem oklch(0 0 0 / 0.3),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.4),
    0 0.125rem 0.375rem oklch(0.45 0.1 50 / 0.3);
  /* Raised dark element: top sheen plus a grounded drop. */
  --shadow-raised:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.09),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.45),
    0 0.3125rem 0.875rem oklch(0 0 0 / 0.3);
  --shadow-raised-sm:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.1),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.45),
    0 0.125rem 0.375rem oklch(0 0 0 / 0.3);
  /* Floating glass panel: hairline sheen, deep soft drop. */
  --shadow-popover:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.07),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.5),
    0 1rem 2.5rem oklch(0 0 0 / 0.5);
  /* Resting card: barely lifted off the canvas. */
  --shadow-card:
    inset 0 0.0625rem 0 oklch(1 0 0 / 0.05),
    0 0.0625rem 0.0625rem oklch(0 0 0 / 0.3),
    0 0.5rem 1.5rem oklch(0 0 0 / 0.25);
  /* Recessed well: fields and tracks pressed into the surface. */
  --shadow-well:
    inset 0 0.0625rem 0.1875rem oklch(0 0 0 / 0.45),
    inset 0 -0.0625rem 0 oklch(1 0 0 / 0.05);

  /* ── Chart palette: all warm leather tones, cognac to cream ────── */
  --chart-1: oklch(0.62 0.115 55);
  --chart-2: oklch(0.78 0.115 72);
  --chart-3: oklch(0.86 0.035 80);
  --chart-4: oklch(0.47 0.095 46);
  --chart-5: oklch(0.55 0.02 70);

  /* --- Motion (soft profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 180ms;
  --transition-duration-base: 240ms;
  --transition-duration-slow: 300ms;
  --ease-out: cubic-bezier(0.19, 1, 0.22, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-in: cubic-bezier(0.895, 0.03, 0.685, 0.22);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-mint: var(--mint);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-highlight: var(--highlight);
  --color-well: var(--well);
  --radius-xs: var(--radius-xs);
  --radius-sm: var(--radius-sm);
  --radius-md: var(--radius-md);
  --radius-lg: var(--radius-lg);
  --radius-xl: var(--radius-xl);
  --radius-2xl: var(--radius-2xl);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family:
      system-ui,
      -apple-system,
      BlinkMacSystemFont,
      ui-sans-serif,
      "Segoe UI",
      Roboto,
      "Helvetica Neue",
      Arial,
      sans-serif;
    letter-spacing: -0.01em;
    -webkit-font-smoothing: antialiased;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: comfortable;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 56);
  --layout-inset: calc(var(--spacing, 0.25rem) * 6);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 8);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 4);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 5);
}

